{"tool":"write","path":"tests/test_export_csv.py","content":"import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic(self):
        rows = [{"a": 1, "b": "x"}, {"a": 2, "b": "y"}]
        self.assertEqual(export_csv(rows, ["a", "b"]), "a,b\r\n1,x\r\n2,y\r\n")

    def test_quoting_and_doubling(self):
        rows = [{"a": 'he said "hi"', "b": "x,y"}]
        self.assertEqual(
            export_csv(rows, ["a", "b"]),
            'a,b\r\n"he said ""hi""","x,y"\r\n',
        )

    def test_embedded_newlines_and_unicode(self):
        rows = [{"a": "line1\nline2\rline3", "b": "caf\u00e9 \u4e2d\u6587"}]
        self.assertEqual(
            export_csv(rows, ["a", "b"]),
            'a,b\r\n"line1\nline2\rline3","caf\u00e9 \u4e2d\u6587"\r\n',
        )

    def test_missing_and_none_and_nonstring(self):
        rows = [{"a": None, "b": 3.5}, {"b": True}]
        self.assertEqual(export_csv(rows, ["a", "b"]), "a,b\r\n,3.5\r\n,True\r\n")

    def test_ignore_unselected_and_column_order(self):
        rows = [{"b": 1, "a": 2, "c": 3}]
        self.assertEqual(export_csv(rows, ["c", "a"]), "c,a\r\n3,2\r\n")

    def test_generators(self):
        def gen_rows():
            yield {"a": 1}
            yield {"a": 2}

        def gen_cols():
            yield "a"

        self.assertEqual(export_csv(gen_rows(), gen_cols()), "a\r\n1\r\n2\r\n")

    def test_empty_rows_and_columns(self):
        self.assertEqual(export_csv([], ["a"]), "a\r\n")
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n\r\n")
        self.assertEqual(export_csv([], []), "\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], [1])
        with self.assertRaises(ValueError):
            export_csv([], [None])

    def test_inputs_not_mutated(self):
        rows = [{"a": 1, "b": 2}]
        columns = ["a", "b"]
        export_csv(rows, columns)
        self.assertEqual(rows, [{"a": 1, "b": 2}])
        self.assertEqual(columns, ["a", "b"])


if __name__ == "__main__":
    unittest.main()
